// Package catalog serves a pinned, build-time snapshot of the models.dev
// catalog (https://models.dev/api.json).
//
// yaah ships the snapshot instead of fetching it at runtime: context-window,
// output-limit, and reasoning questions are answered on every run, and a
// network dependency there would turn somebody else's outage into a local
// failure. data.json is generated by tools/cataloggen; regeneration is manual
// and deliberate (this repo forbids //go:generate):
//
//	go run ./tools/cataloggen
//
// The generator is deterministic, so re-running it over the same upstream
// payload produces a byte-identical file and the diff of a regeneration is a
// reviewable commit.
//
// This package is the third-resolution layer behind config overrides and the
// hand-maintained registries in internal/providers/modelinfo.go: it fills the
// long tail, it does not overrule a deliberate local answer.
package catalog

import (
	"bytes"
	_ "embed"
	"encoding/json"
	"fmt"
	"sort"
	"strings"
	"sync"
)

// schemaVersion is the data.json layout version. Bump it whenever Entry or
// Snapshot change shape so a stale snapshot fails loudly at Parse instead of
// silently decoding into zero values.
const schemaVersion = 1

// SourceURL is the upstream the checked-in snapshot is generated from.
const SourceURL = "https://models.dev/api.json"

//go:embed data.json
var dataJSON []byte

// Entry is the minimal per-model metadata yaah keeps from models.dev. The
// catalog carries roughly nine thousand provider/model pairs; everything yaah
// does not consult (pricing, modalities, release dates) is dropped by the
// generator to keep the embedded payload small.
type Entry struct {
	// Context is the model's context window in tokens (models.dev
	// limit.context). Zero means upstream did not state one.
	Context int `json:"context,omitempty"`
	// Output is the model's maximum output tokens (models.dev
	// limit.output). It is the provider-stated ceiling, so it is safe to use
	// as a cap but never as a target.
	Output int `json:"output,omitempty"`
	// Reasoning reports that the model emits interleaved reasoning
	// (models.dev reasoning).
	Reasoning bool `json:"reasoning,omitempty"`
	// ToolCall reports native tool calling (models.dev tool_call). Carried
	// for later phases; nothing consults it yet.
	ToolCall bool `json:"tool_call,omitempty"`
	// Family is the normalized models.dev family name (e.g. "claude-sonnet").
	Family string `json:"family,omitempty"`
}

// Snapshot is the decoded data.json shape.
type Snapshot struct {
	// Schema is the data.json layout version (see schemaVersion).
	Schema int `json:"schema"`
	// Source records the upstream URL the snapshot came from.
	Source string `json:"source"`
	// Models is keyed by normalized model ID (Normalize): lowercase, no
	// provider prefix, dots preserved.
	Models map[string]Entry `json:"models"`
	// Aliases maps a normalized model ID onto another normalized model ID
	// that the snapshot does know, derived from models.dev
	// canonical_model_id. Aliases never chain and never point at a missing
	// key.
	Aliases map[string]string `json:"aliases,omitempty"`
}

// Parse decodes a snapshot from data.json bytes. Unknown fields are rejected
// so a generator/reader mismatch surfaces as an error rather than as silently
// dropped metadata.
func Parse(data []byte) (*Snapshot, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	var s Snapshot
	if err := dec.Decode(&s); err != nil {
		return nil, fmt.Errorf("catalog: decode snapshot: %w", err)
	}
	if dec.More() {
		return nil, fmt.Errorf("catalog: decode snapshot: trailing data after JSON object")
	}
	if s.Schema != schemaVersion {
		return nil, fmt.Errorf("catalog: snapshot schema %d, want %d (regenerate with go run ./tools/cataloggen)", s.Schema, schemaVersion)
	}
	return &s, nil
}

// Marshal encodes s in the canonical on-disk form: two-space indent, sorted
// object keys (encoding/json sorts map keys), one trailing newline. The
// generator writes exactly these bytes, so re-encoding a checked-in snapshot
// reproduces it byte for byte.
func (s *Snapshot) Marshal() ([]byte, error) {
	b, err := json.MarshalIndent(s, "", "  ")
	if err != nil {
		return nil, fmt.Errorf("catalog: encode snapshot: %w", err)
	}
	return append(b, '\n'), nil
}

// Embedded returns the checked-in snapshot bytes. Tests use it to pin the
// round-trip; production code goes through the lookup helpers.
func Embedded() []byte { return dataJSON }

// Normalize maps a model identifier onto the snapshot's key space: the last
// path segment, lowercased. It mirrors providers.normalizeModelID, so
// "google/gemini-2.5-pro", "models/google/gemini-2.5-pro", and
// "gemini-2.5-pro" all key the same entry. Dots are preserved on purpose:
// "gpt-4.1" must not prefix-match "gpt-4".
func Normalize(name string) string {
	if idx := strings.LastIndexByte(name, '/'); idx >= 0 {
		name = name[idx+1:]
	}
	return strings.ToLower(name)
}

// index is the lookup form of the snapshot, built once per process.
type index struct {
	models   map[string]Entry
	aliases  map[string]string
	families map[string]Entry // family name → conservative representative
}

// loaded decodes the embedded snapshot exactly once. A decode failure means
// the binary was built with a broken data.json, which
// TestEmbeddedSnapshotParses catches in CI; at runtime the catalog then simply
// has no opinion rather than panicking mid-run.
var loaded = sync.OnceValue(func() *index {
	s, err := Parse(dataJSON)
	if err != nil {
		return &index{models: map[string]Entry{}}
	}
	return newIndex(s)
})

// newIndex builds the lookup tables. Iteration follows sorted key order so the
// family representatives are a pure function of the snapshot content.
func newIndex(s *Snapshot) *index {
	ix := &index{
		models:   s.Models,
		aliases:  s.Aliases,
		families: make(map[string]Entry, len(s.Models)/4),
	}
	keys := make([]string, 0, len(s.Models))
	for k := range s.Models {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		family := s.Models[k].Family
		if family == "" {
			continue
		}
		if rep, ok := ix.families[family]; ok {
			ix.families[family] = conservativeMerge(rep, s.Models[k])
			continue
		}
		ix.families[family] = s.Models[k]
	}
	return ix
}

// conservativeMerge combines two members of the same family. Limits keep the
// smallest non-zero value: a family guess must never claim more room than the
// smallest member allows. Capabilities are OR-ed, since a family that contains
// any reasoning model is likely to keep reasoning.
func conservativeMerge(a, b Entry) Entry {
	return Entry{
		Context:   smallestNonZero(a.Context, b.Context),
		Output:    smallestNonZero(a.Output, b.Output),
		Reasoning: a.Reasoning || b.Reasoning,
		ToolCall:  a.ToolCall || b.ToolCall,
		Family:    a.Family,
	}
}

func smallestNonZero(a, b int) int {
	switch {
	case a <= 0:
		return b
	case b <= 0:
		return a
	default:
		return min(a, b)
	}
}

// lookup resolves name in four steps: normalized exact match, then longest
// hyphen-delimited prefix of the model IDs, then longest hyphen-delimited
// prefix of the family names. Prefixes always end on a hyphen, so "gpt-4.1"
// cannot borrow "gpt-4"'s entry.
func (ix *index) lookup(name string) (Entry, bool) {
	key := Normalize(name)
	if key == "" {
		return Entry{}, false
	}
	if target, ok := ix.aliases[key]; ok {
		key = target
	}
	candidates := hyphenPrefixes(key)
	for _, c := range candidates {
		if e, ok := ix.models[c]; ok {
			return e, true
		}
	}
	for _, c := range candidates {
		if e, ok := ix.families[c]; ok {
			return e, true
		}
	}
	return Entry{}, false
}

// hyphenPrefixes returns s followed by every prefix of s that ends just before
// a hyphen, longest first: "gpt-4o-2024-08-06" yields "gpt-4o-2024-08-06",
// "gpt-4o-2024-08", "gpt-4o-2024", "gpt-4o", "gpt". Dots are not boundaries.
func hyphenPrefixes(s string) []string {
	out := make([]string, 1, strings.Count(s, "-")+1)
	out[0] = s
	for i := len(s) - 1; i >= 0; i-- {
		if s[i] == '-' {
			out = append(out, s[:i])
		}
	}
	return out
}

// Lookup returns the snapshot's metadata for modelName. The bool reports
// whether the snapshot knows the model at all; a known model may still have
// zero limits (upstream did not state them).
func Lookup(modelName string) (Entry, bool) {
	return loaded().lookup(modelName)
}

// ContextWindow returns the context window for modelName, or false when the
// snapshot has no positive answer. Callers keep their own config cap: the
// snapshot must never raise a limit the user narrowed.
func ContextWindow(modelName string) (int, bool) {
	e, ok := Lookup(modelName)
	if !ok || e.Context <= 0 {
		return 0, false
	}
	return e.Context, true
}

// OutputLimit returns the provider-stated maximum output tokens for modelName,
// or false when unknown. This is a ceiling, not a target.
func OutputLimit(modelName string) (int, bool) {
	e, ok := Lookup(modelName)
	if !ok || e.Output <= 0 {
		return 0, false
	}
	return e.Output, true
}

// Reasoning reports whether the snapshot flags modelName as an interleaved
// reasoning model. The bool distinguishes "known non-reasoning" from "unknown"
// so callers can keep their own fallbacks for unknown models.
func Reasoning(modelName string) (bool, bool) {
	e, ok := Lookup(modelName)
	if !ok {
		return false, false
	}
	return e.Reasoning, true
}

// Len reports how many model IDs the embedded snapshot carries.
func Len() int { return len(loaded().models) }
